from __future__ import annotations

import re
from typing import Any

UNIFORM_TEMPLATE_PRESETS: dict[str, list[str]] = {
    "SOCCER": ["shirt", "shorts", "socks"],
    "BASKETBALL": ["jersey", "shorts"],
    "BASEBALL": ["jersey", "pants"],
    "SOFTBALL": ["jersey", "pants"],
}

GENERIC_UNIFORM_TEMPLATE = {"slots": ["uniform"]}

KNOWN_UNIFORM_COLORS: dict[str, str] = {
    "black": "#000000",
    "white": "#FFFFFF",
    "red": "#DC2626",
    "blue": "#2563EB",
    "navy": "#1E3A8A",
    "green": "#16A34A",
    "yellow": "#FACC15",
    "gold": "#F59E0B",
    "orange": "#EA580C",
    "purple": "#7C3AED",
    "gray": "#6B7280",
    "grey": "#6B7280",
    "maroon": "#7F1D1D",
    "pink": "#DB2777",
}

UNIFORM_LINE_RE = re.compile(
    r"^\s*(?:uniform|kit|jersey)\s*:\s*(?P<value>.+?)\s*$",
    re.IGNORECASE | re.MULTILINE,
)


def normalize_uniform_slot(value: object) -> str | None:
    slot = str(value or "").strip().lower().replace(" ", "_")
    if not slot:
        return None
    if not re.fullmatch(r"[a-z][a-z0-9_]{0,31}", slot):
        return None
    return slot


def normalize_uniform_template(
    value: object | None,
    *,
    sports_subcategory: str | None = None,
    calendar_type: str | None = None,
) -> dict[str, list[str]]:
    if isinstance(value, dict):
        raw_slots = value.get("slots")
        if isinstance(raw_slots, list):
            slots: list[str] = []
            for raw_slot in raw_slots:
                slot = normalize_uniform_slot(raw_slot)
                if slot and slot not in slots:
                    slots.append(slot)
            if slots:
                return {"slots": slots}

    if calendar_type == "SPORTS" and sports_subcategory:
        preset = UNIFORM_TEMPLATE_PRESETS.get(str(sports_subcategory).upper())
        if preset:
            return {"slots": preset}

    return GENERIC_UNIFORM_TEMPLATE.copy()


def normalize_uniform_value(value: object) -> dict[str, str] | None:
    if isinstance(value, dict):
        label = str(value.get("label") or "").strip()
        hex_value = value.get("hex")
    else:
        label = str(value or "").strip()
        hex_value = None

    if not label:
        return None

    normalized: dict[str, str] = {"label": label}
    if isinstance(hex_value, str) and re.fullmatch(r"#[0-9a-fA-F]{6}", hex_value):
        normalized["hex"] = hex_value.upper()
    else:
        mapped_hex = KNOWN_UNIFORM_COLORS.get(label.lower())
        if mapped_hex:
            normalized["hex"] = mapped_hex
    return normalized


def normalize_event_uniform(value: object | None) -> dict[str, Any]:
    if not isinstance(value, dict):
        return {}

    raw_values = value.get("values")
    if not isinstance(raw_values, dict):
        return {}

    values: dict[str, dict[str, str]] = {}
    for raw_slot, raw_value in raw_values.items():
        slot = normalize_uniform_slot(raw_slot)
        uniform_value = normalize_uniform_value(raw_value)
        if slot and uniform_value:
            values[slot] = uniform_value

    return {"values": values} if values else {}


def parse_uniform_from_description(
    description: str | None,
    template: object | None,
) -> dict[str, Any]:
    if not description:
        return {}

    match = UNIFORM_LINE_RE.search(description)
    if not match:
        return {}

    slots = normalize_uniform_template(template)["slots"]
    raw_parts = [part.strip() for part in re.split(r"\s*/\s*", match.group("value"))]
    parts = [part for part in raw_parts if part]
    if not parts:
        return {}

    values: dict[str, dict[str, str]] = {}
    for index, part in enumerate(parts[: len(slots)]):
        uniform_value = normalize_uniform_value(part)
        if uniform_value:
            values[slots[index]] = uniform_value

    return {"values": values} if values else {}

