def resolve_user_timezone(
    user: User | None,
    *,
    fallback: tzinfo | None = None,
) -> tzinfo:
    """Resolve a user's profile timezone, falling back to `fallback`.

    Falls back when: user is None, profile is missing, profile.timezone is
    blank, or the timezone name is unknown to ZoneInfo. `fallback` defaults
    to `settings.TIME_ZONE`.
    """
    if fallback is None:
        fallback = ZoneInfo(getattr(settings, "TIME_ZONE", "UTC"))
    if user is None:
        return fallback
    try:
        timezone_name = user.profile.timezone
    except (AttributeError, ObjectDoesNotExist):
        return fallback
    if not timezone_name:
        return fallback
    try:
        return ZoneInfo(timezone_name)
    except ZoneInfoNotFoundError:
        return fallback

